Multi-source BFS: enqueue every updated server at minute 0 and count the old servers. Process the queue one level per minute, updating old neighbours in four directions and decrementing the count. If old servers remain when the queue empties, return -1. O(m × n) time and space.

from collections import deque
def minutes_to_update(grid):
    rows, cols = len(grid), len(grid[0])
    queue = deque(); old = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2: queue.append((r, c))
            elif grid[r][c] == 1: old += 1
    minutes = 0
    while queue and old > 0:
        for _ in range(len(queue)):
            r, c = queue.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                    grid[nr][nc] = 2; old -= 1
                    queue.append((nr, nc))
        minutes += 1
    return minutes if old == 0 else -1

Combine a hash map (key → node) with a doubly linked list ordered by recency, with sentinel head (least recent) and tail (most recent). get moves the node to the tail; put updates or inserts at the tail and, if the size exceeds capacity, unlinks the node after head and deletes its key. Every step is O(1). An ordered map with move-to-end (e.g. Python's OrderedDict) is acceptable if the candidate explains the mechanism.

class Node:
    def __init__(self, key=0, val=0):
        self.key, self.val, self.prev, self.next = key, val, None, None

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity; self.map = {}
        self.head, self.tail = Node(), Node()
        self.head.next, self.tail.prev = self.tail, self.head
    def _unlink(self, node):
        node.prev.next, node.next.prev = node.next, node.prev
    def _append(self, node):
        node.prev, node.next = self.tail.prev, self.tail
        self.tail.prev.next = node; self.tail.prev = node
    def get(self, key):
        if key not in self.map: return -1
        node = self.map[key]
        self._unlink(node); self._append(node)
        return node.val
    def put(self, key, value):
        if key in self.map:
            node = self.map[key]; node.val = value
            self._unlink(node); self._append(node)
            return
        node = Node(key, value); self.map[key] = node; self._append(node)
        if len(self.map) > self.cap:
            lru = self.head.next
            self._unlink(lru); del self.map[lru.key]

Two pointers start at both ends. Record the area, then move the pointer at the shorter line inward — moving the taller one can only shrink the width without raising the limiting height. O(n) time, O(1) space.

def max_area(height):
    left, right = 0, len(height) - 1
    best = 0
    while left < right:
        best = max(best, (right - left) * min(height[left], height[right]))
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return best

Modified binary search: at each step at least one half, [low, mid] or [mid, high], is sorted (nums[low] <= nums[mid] means the left half is). If target lies inside the sorted half's range search there, otherwise search the other half. O(log n) time, O(1) space.

def search_rotated(nums, target):
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        if nums[low] <= nums[mid]:            # left half sorted
            if nums[low] <= target < nums[mid]:
                high = mid - 1
            else:
                low = mid + 1
        else:                                 # right half sorted
            if nums[mid] < target <= nums[high]:
                low = mid + 1
            else:
                high = mid - 1
    return -1

Scan every cell; each land cell not yet visited starts a new island, and a DFS/BFS from it marks all 4-directionally connected land as visited (here by overwriting it with "0"). Each cell is processed once: O(m·n) time, O(m·n) worst-case stack.

def num_islands(grid):
    rows, cols = len(grid), len(grid[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "1":
                count += 1
                grid[r][c] = "0"
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == "1":
                            grid[nr][nc] = "0"
                            stack.append((nr, nc))
    return count

Put every value in a hash set. Only start counting from x when x − 1 is absent (x begins a run), then step x + 1, x + 2, … while present. Each value is visited at most twice: O(n) time, O(n) space. Sorting is O(n log n) and earns partial credit.

def longest_consecutive(nums):
    values = set(nums)
    best = 0
    for x in values:
        if x - 1 not in values:
            length = 1
            while x + length in values:
                length += 1
            best = max(best, length)
    return best

Sort, then fix each nums[i] (skipping repeated values) and find pairs summing to −nums[i] with two pointers moving inward; after each hit, move both pointers past equal values. O(n^2) time, O(1) extra space besides the output.

def three_sum(nums):
    nums.sort()
    result = []
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total < 0:
                left += 1
            elif total > 0:
                right -= 1
            else:
                result.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
    return result

Keep a min-heap of the k largest values seen: push each value and pop when the size exceeds k; the heap's top is the answer. O(n log k) time, O(k) space. Quickselect (average O(n)) is also full credit; a full sort is O(n log n) and earns partial credit.

import heapq
def kth_largest(nums, k):
    heap = []
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)
    return heap[0]

Keep four boundaries (top, bottom, left, right). Read the top row, right column, bottom row and left column in turn, shrinking the matching boundary after each pass. Guard the bottom-row and left-column passes with top ≤ bottom and left ≤ right so a lone remaining row or column is not read twice. O(m·n) time.

def spiral_order(matrix):
    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            result.append(matrix[top][c])
        top += 1
        for r in range(top, bottom + 1):
            result.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1):
                result.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                result.append(matrix[r][left])
            left += 1
    return result

Breadth-first search with a queue. At the start of each level record the queue's length, pop exactly that many nodes, collect their values and push their non-null children. O(n) time, O(w) space (w = widest level).

from collections import deque
# TreeNode has fields val, left and right
def level_order(root):
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)
    return result

Recurse with an allowed open range (low, high): going left narrows high to the node's value, going right narrows low. Use ±infinity (or null) as the initial bounds so values at the 32-bit limits work. O(n) time, O(h) stack. An in-order traversal that checks values are strictly increasing is equally valid.

# TreeNode has fields val, left and right
def is_valid_bst(root):
    def check(node, low, high):
        if not node:
            return True
        if not (low < node.val < high):
            return False
        return check(node.left, low, node.val) and check(node.right, node.val, high)
    return check(root, float('-inf'), float('inf'))

Dynamic programming: best(i) = max(best(i − 1), nums[i] + best(i − 2)) — skip house i or take it. Only the last two values are needed, so O(n) time and O(1) space.

def rob(nums):
    prev2, prev1 = 0, 0
    for x in nums:
        prev2, prev1 = prev1, max(prev1, prev2 + x)
    return prev1

Iterative build-up: start with [[]]; for each number, copy every existing subset and append the number to the copy. Backtracking (include/exclude each index) or bitmasks 0 … 2^n − 1 are equally valid. O(n·2^n) time, which is the size of the output.

def subsets(nums):
    result = [[]]
    for x in nums:
        result += [s + [x] for s in result]
    return result

Dutch National Flag: pointers low, mid and high; everything before low is 0 and everything after high is 2. If nums[mid] is 0, swap with nums[low] and advance both; if 1, advance mid; if 2, swap with nums[high] and decrement high only (the swapped-in value is still unchecked). One pass, O(n) time, O(1) space. A two-pass counting rewrite earns most credit.

def sort_colors(nums):
    low, mid, high = 0, 0, len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1

def most_frequent(s):
    freq, first = {}, {}
    for i, w in enumerate(s.split()):
        freq[w] = freq.get(w, 0) + 1
        if w not in first: first[w] = i
    best = max(freq, key=lambda w: (freq[w], -first[w]))
    return f"{best} {freq[best]}"

def count_levels(logs):
    freq = {}
    for lvl in logs.split():
        freq[lvl] = freq.get(lvl, 0) + 1
    return freq

def dedupe_consecutive(msgs):
    out = []
    for m in msgs:
        if not out or out[-1] != m:
            out.append(m)
    return out

