Index both snapshots by id in hash maps, then classify ids by membership and compare the records of shared ids field-by-field (including key sets). O((n + m) log(n + m)) for the final sorts, O(n + m) space. Sorting both snapshots by id and merging with two pointers is an accepted alternative.

def diff_snapshots(old, new):
    old_by_id = {r["id"]: r for r in old}
    new_by_id = {r["id"]: r for r in new}
    added = sorted(k for k in new_by_id if k not in old_by_id)
    removed = sorted(k for k in old_by_id if k not in new_by_id)
    changed = sorted(k for k in old_by_id if k in new_by_id and old_by_id[k] != new_by_id[k])
    return {"added": added, "removed": removed, "changed": changed}

Classify each non-empty value with small pattern checks (or regexes), collect the set of types seen, then decide: empty → unknown, one type → it, {integer, float} → float, otherwise string. O(total characters) time. Hand-written character checks instead of regexes are equally fine.

import re

def classify(v):
    if v.lower() in ("true", "false"):
        return "boolean"
    if re.fullmatch(r"-?[0-9]+", v):
        return "integer"
    if re.fullmatch(r"-?[0-9]+\.[0-9]+", v):
        return "float"
    m = re.fullmatch(r"[0-9]{4}-([0-9]{2})-([0-9]{2})", v)
    if m and 1 <= int(m.group(1)) <= 12 and 1 <= int(m.group(2)) <= 31:
        return "date"
    return "string"

def infer_column_type(values):
    seen = {classify(v) for v in values if v is not None and v != ""}
    if not seen:
        return "unknown"
    if len(seen) == 1:
        return seen.pop()
    if seen == {"integer", "float"}:
        return "float"
    return "string"

Keep a queue of accepted timestamps; for each request pop timestamps ≤ t − window from the front, accept (and push) if the queue size is below the limit. Each timestamp is pushed and popped at most once, so O(n) time and O(limit) space.

from collections import deque

def rate_limit(timestamps, limit, window):
    accepted, result = deque(), []
    for t in timestamps:
        while accepted and accepted[0] <= t - window:
            accepted.popleft()
        if len(accepted) < limit:
            accepted.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

Parse the fields, add the minutes to the minute-of-day, carry whole days, then advance the date one day at a time using a days-in-month function with the leap-year rule (at most ~700 days for the constraints). Converting to a day count since an epoch and back is an accepted O(1)-style alternative.

def is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

def days_in_month(y, m):
    if m == 2:
        return 29 if is_leap(y) else 28
    return 30 if m in (4, 6, 9, 11) else 31

def add_minutes(timestamp, minutes):
    y, mo, d = int(timestamp[0:4]), int(timestamp[5:7]), int(timestamp[8:10])
    hh, mm, ss = int(timestamp[11:13]), int(timestamp[14:16]), timestamp[17:19]
    total = hh * 60 + mm + minutes
    extra_days, total = divmod(total, 1440)
    for _ in range(extra_days):
        d += 1
        if d > days_in_month(y, mo):
            d, mo = 1, mo + 1
            if mo > 12:
                mo, y = 1, y + 1
    return "%04d-%02d-%02dT%02d:%02d:%sZ" % (y, mo, d, total // 60, total % 60, ss)

